float QuadCurve(vec2 uv, float p, float a, float b, float c, float d, float e, float f){

    float x = uv.x,
          y = uv.y;

    return p/abs(a*x*x + 2.*b*x*y + c*y*y + d*x + e*y -f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates 
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x/iResolution.y;

    float t = iTime,
          w = .5,
          phi=1.;
    float bri = QuadCurve(uv, 0.02, 
                10.*sin(0.25*w*t+3.14/2.+phi), 
                20.*sin(0.5*w*t+0.5+phi), 
                20.*sin(1.*w*t+phi), 
                 2.*sin(0.1*w*t+phi), 
                 2.*sin(0.1*w*t+phi+3.41), 
                 .5*sin(0.5*w*t+phi));

          bri += QuadCurve(uv, 0.02, 
                 20.*sin(1.*w*t+phi),
                 10.*sin(0.25*w*t+3.14/2.+phi), 
                 20.*sin(0.3*w*t+phi), 
                  2.*sin(0.1*w*t+phi), 
                  2.*sin(0.2*w*t+phi+3.41), 
                  .5*sin(0.5*w*t+phi));

          bri += QuadCurve(uv, 0.02, 
                 20.*sin(0.9*w*t+phi+3.14/2.),
                 10.*sin(0.25*w*t+phi), 
                 20.*sin(0.4*w*t+phi), 
                  2.*sin(0.5*w*t+phi), 
                  2.*sin(0.6*w*t+phi+3.41), 
                  .5*sin(0.7*w*t+phi));

          bri += QuadCurve(uv, 0.02, 
                 20.*sin(0.9*w*t+phi),
                 10.*sin(0.3*w*t+phi), 
                 20.*sin(0.5*w*t+phi+3.14/2.), 
                  2.*sin(0.5*w*t+phi), 
                  2.*sin(0.6*w*t+phi+3.41), 
                  .5*sin(0.2*w*t+phi));

          bri += QuadCurve(uv, 0.02, 
                 20.*sin(0.9*w*t+phi+3.14/3.),
                 10.*sin(0.25*w*t+phi), 
                 20.*sin(0.4*w*t+phi+3.14/4.), 
                  2.*sin(0.5*w*t+phi), 
                  2.*sin(0.6*w*t+phi+3.41), 
                  .5*sin(0.7*w*t+phi));

          bri *= 0.2;
    // Output to screen
    fragColor = vec4(bri);
    }
